if(PHP_SAPI!=='cli'||getenv('NORWAY_SYNTHETIC_TEST')!=='1'||getenv('DOLI_DB_NAME')!=='norway_test'){exit(1);}
require '/var/www/html/master.inc.php';require_once DOL_DOCUMENT_ROOT.'/core/lib/admin.lib.php';require_once DOL_DOCUMENT_ROOT.'/fourn/class/fournisseur.facture.class.php';require_once DOL_DOCUMENT_ROOT.'/custom/norway/class/NorwayPostingEvidence.php';
function ndAssert($ok,$message){if(!$ok){throw new RuntimeException($message);}}
function ndSql($sql){global $db;$r=$db->query($sql);ndAssert((bool)$r,'Synthetic no-deduction query failed');return $r;}
ndAssert($user->fetch('','testadmin')>0,'Admin missing');$user->loadRights('',1);$p=$db->prefix();$entity=(int)$conf->entity;$run=bin2hex(random_bytes(4));
$supplier=$db->fetch_object(ndSql("SELECT rowid FROM ".$p."societe WHERE entity=".$entity." AND nom LIKE 'SYNTHETIC SUPPLIER ONLY %' ORDER BY rowid DESC LIMIT 1"));ndAssert((bool)$supplier,'Supplier fixture missing');
$account=$db->fetch_object(ndSql("SELECT a.rowid FROM ".$p."accounting_account a JOIN ".$p."accounting_system s ON s.pcg_version=a.fk_pcg_version WHERE a.entity=".$entity." AND s.rowid=".(int)getDolGlobalString('CHARTOFACCOUNTS')." AND a.account_number='4000' LIMIT 1"));ndAssert((bool)$account,'Purchase account missing');
$invoices=array();foreach(array(array(0,100),array(2,-20)) as $case){$invoice=new FactureFournisseur($db);$invoice->socid=(int)$supplier->rowid;$invoice->date=dol_mktime(12,0,0,1,10,2026);$invoice->type=$case[0];$invoice->ref_supplier='SYND-'.$run.'-'.$case[0];$invoice->multicurrency_code='NOK';$invoice->multicurrency_tx=1;if($case[0]===2){$invoice->fk_facture_source=$invoices[0]->id;}ndAssert($invoice->create($user)>0,'No-deduction invoice failed');ndAssert($invoice->addline('Synthetic no-deduction comparison',$case[1],25,0,0,1,0,0,0,0,(int)$account->rowid)>0,'No-deduction line failed');ndAssert($invoice->validate($user,'SYND-'.$run.'-'.$case[0])>0,'No-deduction validation failed');$invoices[]=$invoice;}
ndSql("INSERT INTO ".$p."accounting_journal (entity,code,label,nature,active) VALUES (".$entity.",'SYND-".$run."','Synthetic no deduction',3,1)");$journal=(int)$db->last_insert_id($p.'accounting_journal');
$name='ACCOUNTING_PURCHASES_DO_NOT_DISPATCH_TAXES';$previous=$db->fetch_object(ndSql("SELECT value FROM ".$p."const WHERE entity=".$entity." AND name='".$name."'"));
$cookie=tempnam(sys_get_temp_dir(),'norway-no-deduction-');$curl=curl_init();curl_setopt_array($curl,array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>30));
function ndHttp($path,$post=null){global $curl;curl_setopt($curl,CURLOPT_URL,'http://localhost'.$path);curl_setopt($curl,CURLOPT_POST,$post!==null);if($post!==null){curl_setopt($curl,CURLOPT_POSTFIELDS,http_build_query($post));}$body=curl_exec($curl);ndAssert($body!==false&&curl_getinfo($curl,CURLINFO_HTTP_CODE)<400,'No-deduction HTTP failed');return $body;}
function ndToken($body){ndAssert(preg_match('/name="token"[^>]*value="([^"]+)"/',$body,$m)===1,'Token missing');return html_entity_decode($m[1]);}
try{
 // Existing core-wide option is used only in this isolated synthetic experiment.
 ndAssert(dolibarr_set_const($db,$name,'1','chaine',0,'',$entity)>0,'No-tax-dispatch fixture failed');
 $body=ndHttp('/index.php');ndHttp('/index.php',array('token'=>ndToken($body),'actionlogin'=>'login','loginfunction'=>'loginfunction','username'=>'testadmin','password'=>getenv('DOLI_ADMIN_PASSWORD')));
 $params=array('id_journal'=>$journal,'date_startday'=>1,'date_startmonth'=>1,'date_startyear'=>2026,'date_endday'=>31,'date_endmonth'=>12,'date_endyear'=>2026,'in_bookkeeping'=>'notyet');$path='/accountancy/journal/purchasesjournal.php?'.http_build_query($params);$body=ndHttp($path);ndHttp($path,$params+array('token'=>ndToken($body),'action'=>'writebookkeeping'));
 foreach($invoices as $invoice){$report=NorwayPostingEvidence::report($db,$entity,(int)$invoice->id,$user,'purchase25none','supplier_invoice');ndAssert($report['status']==='Grouped'&&$report['deduction_basis_points']===0,'Native no-deduction purchase/credit mismatch');ndAssert(NorwayPostingEvidence::report($db,$entity,(int)$invoice->id,$user,'purchase25full','supplier_invoice')['status']==='Different','No deduction inferred as full');}
 $invoice=$invoices[0];$before=$db->fetch_object(ndSql("SELECT SUM(debit) AS d,SUM(credit) AS c FROM ".$p."accounting_bookkeeping WHERE entity=".$entity." AND doc_type='supplier_invoice' AND fk_doc=".(int)$invoice->id));
 foreach(array('nb_NO','en_US') as $locale){$body=html_entity_decode(ndHttp('/fourn/facture/card.php?facid='.(int)$invoice->id.'&norway_purchase_profile=purchase25partial&norway_purchase_share=50&lang='.$locale),ENT_QUOTES,'UTF-8');ndAssert(strpos($body,'NorwayPurchase')===false&&strpos($body,'50.00 %')!==false&&strpos($body,$locale==='nb_NO'?'Bokføringen avviker':'Postings differ')!==false,'Explicit partial comparison missing/untranslated');}
 $body=html_entity_decode(ndHttp('/fourn/facture/card.php?facid='.(int)$invoice->id.'&norway_purchase_profile=purchase25partial&lang=nb_NO'),ENT_QUOTES,'UTF-8');ndAssert(strpos($body,'0,01 og 99,99')!==false,'Missing percentage silently defaulted');
 $after=$db->fetch_object(ndSql("SELECT SUM(debit) AS d,SUM(credit) AS c FROM ".$p."accounting_bookkeeping WHERE entity=".$entity." AND doc_type='supplier_invoice' AND fk_doc=".(int)$invoice->id));ndAssert($before==$after,'Comparison changed ledger');
}finally{if($previous){ndAssert(dolibarr_set_const($db,$name,$previous->value,'chaine',0,'',$entity)>0,'Core option restore failed');}else{ndSql("DELETE FROM ".$p."const WHERE entity=".$entity." AND name='".$name."'");}curl_close($curl);@unlink($cookie);}
print "PASS native no-deduction purchase/credit, explicit partial HTTP comparison, missing-share rejection, read-only ledger and restored core option\n";
